import json
import os
import pandas as pd
from pathlib import Path

def validate_file_exists(file_path):
    if not os.path.exists(file_path):
        return {
            "check_name": f"file_exists_{Path(file_path).name}",
            "passed": False,
            "message": f"File {file_path} does not exist"
        }
    return {
        "check_name": f"file_exists_{Path(file_path).name}",
        "passed": True,
        "message": f"File {file_path} exists"
    }

def validate_file_not_empty(file_path):
    if os.path.getsize(file_path) == 0:
        return {
            "check_name": f"file_not_empty_{Path(file_path).name}",
            "passed": False,
            "message": f"File {file_path} is empty"
        }
    return {
        "check_name": f"file_not_empty_{Path(file_path).name}",
        "passed": True,
        "message": f"File {file_path} is not empty"
    }

def validate_csv_columns(file_path, expected_columns):
    try:
        df = pd.read_csv(file_path)
        if set(df.columns) != set(expected_columns):
            return {
                "check_name": f"columns_match_{Path(file_path).name}",
                "passed": False,
                "message": f"Columns in {file_path} do not match expected columns"
            }
        return {
            "check_name": f"columns_match_{Path(file_path).name}",
            "passed": True,
            "message": f"Columns in {file_path} match expected columns"
        }
    except Exception as e:
        return {
            "check_name": f"columns_match_{Path(file_path).name}",
            "passed": False,
            "message": f"Error reading {file_path}: {str(e)}"
        }

def validate_csv_row_count(file_path, expected_min_rows):
    try:
        df = pd.read_csv(file_path)
        if len(df) < expected_min_rows:
            return {
                "check_name": f"min_rows_{Path(file_path).name}",
                "passed": False,
                "message": f"{file_path} has fewer rows than expected"
            }
        return {
            "check_name": f"min_rows_{Path(file_path).name}",
            "passed": True,
            "message": f"{file_path} has sufficient rows"
        }
    except Exception as e:
        return {
            "check_name": f"min_rows_{Path(file_path).name}",
            "passed": False,
            "message": f"Error reading {file_path}: {str(e)}"
        }

def run_validations():
    validations = []

    # Validate t01_selected_indicators.csv
    validations.append(validate_file_exists("outputs/t01_selected_indicators.csv"))
    validations.append(validate_file_not_empty("outputs/t01_selected_indicators.csv"))
    validations.append(validate_csv_columns("outputs/t01_selected_indicators.csv", ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]))
    validations.append(validate_csv_row_count("outputs/t01_selected_indicators.csv", 10))

    # Validate t05_clean_stops.csv
    validations.append(validate_file_exists("outputs/t05_clean_stops.csv"))
    validations.append(validate_file_not_empty("outputs/t05_clean_stops.csv"))
    validations.append(validate_csv_columns("outputs/t05_clean_stops.csv", ["stop_id", "stop_name", "stop_lat", "stop_lon"]))
    validations.append(validate_csv_row_count("outputs/t05_clean_stops.csv", 400))

    # Validate t08_pois_clean.csv
    validations.append(validate_file_exists("outputs/t08_pois_clean.csv"))
    validations.append(validate_file_not_empty("outputs/t08_pois_clean.csv"))
    validations.append(validate_csv_columns("outputs/t08_pois_clean.csv", ["qid", "label", "poi_type", "latitude", "longitude", "source"]))
    validations.append(validate_csv_row_count("outputs/t08_pois_clean.csv", 40))

    # Validate t10_accessibility_scores.csv
    validations.append(validate_file_exists("outputs/t10_accessibility_scores.csv"))
    validations.append(validate_file_not_empty("outputs/t10_accessibility_scores.csv"))
    validations.append(validate_csv_columns("outputs/t10_accessibility_scores.csv", ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]))
    validations.append(validate_csv_row_count("outputs/t10_accessibility_scores.csv", 40))

    # Validate t13_city_clusters.csv
    validations.append(validate_file_exists("outputs/t13_city_clusters.csv"))
    validations.append(validate_file_not_empty("outputs/t13_city_clusters.csv"))

    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(validations, f, indent=2)

if __name__ == "__main__":
    run_validations()
</solution_file>

